<script setup lang="ts">
import {onMounted,ref} from 'vue'
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>}>()
type Row=Record<string,any>
const profiles=ref<Row[]>([]),clients=ref<Row[]>([]),editing=ref<Row|null>(null),removing=ref<Row|null>(null),busy=ref(false),error=ref('')
async function load(){[profiles.value,clients.value]=await Promise.all([props.api('client-profiles'),props.api('client-catalog')])}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
function create(){editing.value={name:'',format:'mihomo',local_port:7890,selection:'select',test_url:'https://www.gstatic.com/generate_204',extra_text:'{}',version:0}}
function edit(p:Row){editing.value={...p,extra_text:p.extra_text??JSON.stringify(p.extra_config??{},null,2)}}
function save(){void run(async()=>{const p=editing.value!;await props.api('client-profiles'+(p.id?'/'+p.id:''),p.id?'PUT':'POST',{name:p.name,format:p.format,local_port:p.local_port,selection:p.selection,test_url:p.test_url,extra_text:p.extra_text,version:p.version});editing.value=null;await load()})}
function remove(){void run(async()=>{await props.api('client-profiles/'+removing.value!.id,'DELETE');removing.value=null;await load()})}
onMounted(()=>void run(load))
</script>
<template><section class="preset-workspace"><h3>订阅输出预设（兼容已有模板）</h3><p class="muted">常规基础、DNS、策略组和规则请使用客户端策略。输出预设固定客户端格式与本地参数；已有覆盖保留并最后生效，仅在特定订阅需要例外配置时使用。</p><button class="secondary" @click="create">＋ 添加输出预设</button><p v-if="error&&!editing&&!removing" class="error">{{error}}</p><div class="table-scroll"><table><thead><tr><th>名称</th><th>格式</th><th>覆盖优先级</th><th>操作</th></tr></thead><tbody><tr v-for="p in profiles" :key="p.id"><td>{{p.name}}</td><td>{{p.format}}</td><td>客户端策略之后生效</td><td><button class="text-button" @click="edit(p)">编辑输出预设</button> <button class="text-button danger" @click="removing=p">删除</button></td></tr></tbody></table></div><p v-if="!profiles.length" class="muted">无历史预设。新订阅直接使用客户端策略。</p></section>
<div v-if="editing" class="modal-backdrop"><form class="modal" role="dialog" aria-label="输出预设" @submit.prevent="save"><div class="modal-heading"><h2>{{editing.id?'编辑':'添加'}}输出预设</h2><button type="button" class="secondary" @click="editing=null">关闭</button></div><div class="form-content"><p v-if="error" class="error">{{error}}</p><div class="fields"><label>名称<input v-model="editing.name" required maxlength="100"></label><label>客户端格式<select v-model="editing.format"><option v-for="c in clients" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>本地端口<input v-model.number="editing.local_port" type="number" min="1024" max="65535" required></label><label>默认节点选择<select v-model="editing.selection"><option value="select">手动选择</option><option value="urltest">自动测速</option></select></label><label>测速 URL<select v-model="editing.test_url"><option>https://www.gstatic.com/generate_204</option><option>https://cp.cloudflare.com/generate_204</option></select></label></div><p class="form-note">原生覆盖只适用于所选格式，优先于用户客户端策略。已有订阅继续使用原预设；新订阅可留空。客户端入站仍限制回环地址。</p><label class="wide-field">高级：原生配置覆盖 JSON / YAML<textarea v-model="editing.extra_text" class="native-preview" rows="14" maxlength="32768" spellcheck="false"></textarea></label></div><div class="modal-footer"><button type="button" class="secondary" @click="editing=null">取消</button><button class="primary" :disabled="busy">保存</button></div></form></div>
<div v-if="removing" class="modal-backdrop"><section class="modal" role="dialog" aria-label="删除输出预设"><div class="form-content"><h2>删除 {{removing.name}}？</h2><p>关联订阅恢复使用客户端策略；节点与用户权限保留。</p><p v-if="error" class="error">{{error}}</p></div><div class="modal-footer"><button class="secondary" @click="removing=null">取消</button><button class="primary" :disabled="busy" @click="remove">确认删除</button></div></section></div></template>
<style scoped>.preset-workspace{margin-top:20px}.preset-workspace p{font-size:12px;line-height:1.8}</style>
